using Microsoft.AspNetCore.Diagnostics;using Microsoft.EntityFrameworkCore;using RandomNumbersApi.Data;using RandomNumbersApi.Services;var builder = WebApplication.CreateBuilder(args);builder.Logging.ClearProviders();builder.Logging.AddConsole();builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();builder.Services.AddDbContext<ApplicationDbContext>(options =>{options.UseSqlite(builder.Configuration.GetConnectionString("DefaultConnection"));});builder.Services.AddScoped<IRandomNumberService, RandomNumberService>();builder.Services.AddScoped<IItemService, ItemService>();var app = builder.Build();if(app.Environment.IsDevelopment()){app.UseDeveloperExceptionPage();app.UseSwagger();app.UseSwaggerUI();}else{app.UseExceptionHandler("/error");app.UseHsts();}app.Map("/error", (HttpContext httpContext) =>{var feature = httpContext.Features.Get<IExceptionHandlerFeature>();var problem = Results.Problem(title: "An unexpected error occurred.", detail: feature?.Error.Message, statusCode: StatusCodes.Status500InternalServerError);return problem;}).ExcludeFromDescription();app.UseHttpsRedirection();app.UseRouting();app.MapControllers();using (var scope = app.Services.CreateScope()){var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();await db.Database.EnsureCreatedAsync();}app.Run();